    // ---------- 幂等 ----------

    @Test
    void pairPublishIdempotentReplayAndParamConflict() throws Exception {
        String pairKey = key("NP");
        String first = key("SCH");
        String second = key("SCH");
        createPlan(first, DAY, true, pairKey, occ("G1", key("SEC"), iso(22), iso(6, 1)));
